#nullable enable // autogenerated

using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.tanookiZombie_Animation)]
    public class TanookiZombie_AnimationBehaviour : HumanoidAnimationBehaviour
    {
        public TanookiZombie_AnimationBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override void ModifyAnimationParameters(Entity entity, int state, ref AnimationParameters parameters)
        {
            base.ModifyAnimationParameters(entity, state, ref parameters);
            if (state == STATE_JUMP)
            {
                parameters.walkState = WALK_STATE_NONE;
                parameters.armState = ARM_STATE_NONE;
                parameters.specialState = SPECIAL_STATE_JUMP;
            }
        }
        public const int STATE_JUMP = VanillaEnemyStates.TANOOKI_ZOMBIE_JUMP;
        public const int SPECIAL_STATE_JUMP = 1;
    }
}